-- CarQ taxonomy import: make / model / variant (merge, idempotent)
-- makes=452 models=5871 variants=22394 (from 118274 trims)
-- Safe to re-run. Run:  mysql -u <user> -p <database> < taxonomy_import.sql

SET NAMES utf8mb4;
SET autocommit=0;
START TRANSACTION;

CREATE TEMPORARY TABLE _mk (name VARCHAR(191)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE _md (make VARCHAR(191), name VARCHAR(191)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE _vr (make VARCHAR(191), model VARCHAR(191), name VARCHAR(191)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

