INSERT IGNORE INTO `CarMake` (`name`,`createdAt`,`updatedAt`)
  SELECT DISTINCT name, NOW(3), NOW(3) FROM _mk;

INSERT IGNORE INTO `CarModel` (`name`,`makeId`,`createdAt`,`updatedAt`)
  SELECT DISTINCT d.name, m.id, NOW(3), NOW(3)
  FROM _md d JOIN `CarMake` m ON m.name = d.make;

INSERT IGNORE INTO `CarVariant` (`name`,`modelId`,`createdAt`,`updatedAt`)
  SELECT DISTINCT v.name, md.id, NOW(3), NOW(3)
  FROM _vr v
  JOIN `CarMake` m  ON m.name = v.make
  JOIN `CarModel` md ON md.makeId = m.id AND md.name = v.model;

COMMIT;
SELECT (SELECT COUNT(*) FROM `CarMake`) AS makes,
       (SELECT COUNT(*) FROM `CarModel`) AS models,
       (SELECT COUNT(*) FROM `CarVariant`) AS variants;
